INSERT INTO posts (title, category, date, read_time, excerpt, image, featured, sort_order, active, eyebrow, lead, secondary_image, author, sections) VALUES
('Créer un site web au Cameroun : comment faire et par où commencer', 'Guide', '24 juillet 2026', '5 min', 'Vous voulez créer un site web au Cameroun mais vous ne savez pas par où commencer ? Voici les étapes, en mots simples, avec le temps que ça prend et ce que ça coûte.', '/images/service-blog.jpg', 0, 20, 1, 'On vous explique tout, en mots simples', 'Pour créer un site web au Cameroun, il faut 5 choses : un nom (le nom de domaine), un endroit pour ranger le site (l’hébergement), un design simple qui marche bien sur le téléphone, du texte clair, et le mettre sur Google. Ça prend en général 2 à 4 semaines.', '/images/process-visual.jpg', 'L’équipe IMPACT TECH', '[{"title":"D’abord, à quoi va servir votre site ?","paragraphs":["Avant de penser au design, posez-vous une seule question : ce site, il sert à quoi ? À recevoir des appels et des messages ? À vendre vos produits ? À montrer votre travail ? La réponse change tout.","Un site qui veut tout faire ne fait rien de bien. Choisissez UNE chose importante, et le site sera clair."],"bullets":["Recevoir des clients → un site simple + bouton WhatsApp","Vendre → une boutique en ligne avec MoMo et Orange Money","Tester une offre → une seule page qui donne envie"]},{"title":"Le nom et l’endroit où vit le site","paragraphs":["Le nom de domaine, c’est l’adresse de votre site (par exemple : votreentreprise.com). On le paie une fois par an. Prenez un nom court, facile à dire au téléphone, sans faute possible.","L’hébergement, c’est l’endroit où le site est rangé pour rester en ligne jour et nuit. Un bon hébergement rend le site rapide, même quand la connexion est faible. Évitez le « gratuit » qui met de la pub ou qui coupe."],"quote":"Un site sérieux tient sur trois choses : un bon nom, un hébergement fiable, et le petit cadenas de sécurité (https)."},{"title":"Le site doit être beau ET rapide sur le téléphone","paragraphs":["Au Cameroun, presque tout le monde ouvre les sites sur son téléphone. Votre site doit donc bien s’afficher sur mobile : gros boutons, texte facile à lire, photos qui chargent vite.","Pour le texte, allez droit au but : qui vous êtes, ce que vous faites, pourquoi on peut vous faire confiance (avis, réalisations), et comment vous joindre."],"callout":"À retenir : un site rapide et clair sur le téléphone ramène plus de clients qu’un site « joli » mais lent. La vitesse et la clarté d’abord."},{"title":"Le mettre sur Google","paragraphs":["Un site ne se met pas tout seul sur Google. Il faut le déclarer à Google (Search Console) et créer votre fiche Google (celle qui apparaît sur la carte). C’est ça qui vous rend trouvable.","Après, plus vous publiez des articles utiles (comme celui-ci), plus Google vous montre. C’est long au début, puis ça grossit tout seul."]}]'),
('Combien coûte un site web au Cameroun ?', 'Guide', '21 juillet 2026', '5 min', 'Combien coûte un site web au Cameroun ? Une page simple, un site vitrine, une boutique en ligne : voici les vrais prix et ce qui les fait monter ou baisser.', '/images/blog-2.jpg', 0, 21, 1, 'Des prix clairs, sans surprise', 'Au Cameroun, une page simple (landing page) coûte environ 200 000 FCFA, un site vitrine environ 300 000 FCFA, et une boutique en ligne à partir de 500 000 FCFA. Le prix dépend surtout de ce que le site doit faire, pas du nombre de pages.', '/images/service-landing.jpg', 'L’équipe IMPACT TECH', '[{"title":"Ce que vous payez vraiment","paragraphs":["Quand vous payez un site, vous ne payez pas juste « des pages ». Vous payez le design, le travail technique, le nom de domaine, l’hébergement la première année, la sécurité, et la mise en ligne.","Un prix trop bas cache souvent quelque chose : pas d’hébergement, pas de sécurité, pas de suivi. Vous payez moins au début, mais plus après."],"bullets":["Le design et le développement","Le nom de domaine + l’hébergement 1 an","La sécurité (le cadenas https)","La mise en ligne et un peu de référencement"]},{"title":"Quel type de site pour quel budget ?","paragraphs":["Une seule page suffit pour une offre précise ou une pub. Un site vitrine présente toute votre activité. Une boutique en ligne ajoute le catalogue, le paiement et les commandes : c’est plus de travail, donc plus cher.","Le bon budget, c’est celui qui répond à VOTRE besoin, pas celui du concurrent d’à côté."],"quote":"Le site le plus rentable n’est pas le plus cher : c’est celui qui règle le bon problème pour votre business."},{"title":"Et après ? Ce qu’il reste à payer","paragraphs":["La première année, tout est compris. À partir de la 2ᵉ année, il reste juste à renouveler le nom de domaine et l’hébergement : un petit montant, dit à l’avance.","Demandez toujours ce qui est inclus, à qui appartient le site, et si vous pourrez le modifier vous-même. Un bon devis répond à ces questions sans hésiter."],"callout":"À retenir : demandez un devis qui sépare bien 3 choses : la création, le coût chaque année, et les évolutions futures. Pas de flou."}]'),
('C’est quoi un SaaS ? Explication simple avec des exemples au Cameroun', 'Guide', '17 juillet 2026', '5 min', 'SaaS, ça veut dire quoi ? En clair : un logiciel qu’on utilise directement sur internet, sans rien installer, souvent avec un abonnement. Exemples et cas concrets au Cameroun.', '/images/service-saas.jpg', 0, 22, 1, 'Le mot compliqué, expliqué simplement', 'Un SaaS, c’est un logiciel qu’on utilise sur internet, sans l’installer sur son ordinateur, en payant un petit abonnement (par mois ou par an). Vous en utilisez déjà : une boîte mail comme Gmail, ou un outil de gestion en ligne, c’est du SaaS.', '/images/project-school.jpg', 'L’équipe IMPACT TECH', '[{"title":"En clair, un SaaS c’est quoi ?","paragraphs":["Avant, on achetait un logiciel et on l’installait sur chaque ordinateur. Avec un SaaS, tout est en ligne : vous ouvrez juste une page web, vous vous connectez, et ça marche. Rien à installer, rien à mettre à jour soi-même.","On paie un petit montant régulier au lieu d’une grosse somme d’un coup. Et on peut l’utiliser depuis n’importe quel téléphone ou ordinateur."],"bullets":["Pas d’installation : ça marche dans le navigateur","Un abonnement au lieu d’un gros achat","Accessible partout, sur téléphone comme sur PC","Les mises à jour se font toutes seules"]},{"title":"Des exemples concrets au Cameroun","paragraphs":["Un logiciel de gestion de stock pour plusieurs boutiques, un outil de suivi de livraisons, une plateforme pour gérer les notes des élèves, un système de réservation pour un salon… tout ça peut être un SaaS.","L’idée est toujours la même : remplacer les cahiers et les fichiers Excel éparpillés par un seul outil en ligne, propre et partagé par toute l’équipe."],"quote":"Un SaaS, c’est simplement un outil de travail en ligne. Le mot fait peur, mais l’idée est facile : tout au même endroit, accessible partout."},{"title":"Est-ce fait pour vous ?","paragraphs":["Si vous perdez du temps avec des fichiers Excel, des cahiers ou WhatsApp pour gérer votre activité, un SaaS peut vous faire gagner beaucoup de temps et éviter les erreurs.","On commence toujours petit : une première version qui règle votre problème le plus urgent, testée avec vos vraies équipes, puis on ajoute le reste."],"callout":"À retenir : un SaaS = un logiciel en ligne, par abonnement, accessible partout. Idéal pour remplacer les fichiers Excel et mieux gérer son activité."}]'),
('Comment vendre en ligne au Cameroun ?', 'Guide', '12 juillet 2026', '5 min', 'Vendre en ligne au Cameroun, c’est possible même sans gros budget. Voici comment démarrer simplement, avec le paiement MoMo et la livraison.', '/images/service-ecommerce.jpg', 0, 23, 1, 'De vos premiers produits à vos premières ventes', 'Pour vendre en ligne au Cameroun, commencez avec vos meilleurs produits, une boutique simple qui marche bien sur le téléphone, le paiement Mobile Money (MTN MoMo et Orange Money), et une livraison claire. On démarre petit, on regarde ce qui marche, puis on ajoute le reste.', '/images/project-ecommerce.jpg', 'L’équipe IMPACT TECH', '[{"title":"Commencez petit, mais commencez vraiment","paragraphs":["Beaucoup veulent tout mettre en ligne le premier jour. Mauvaise idée. Prenez 10 à 20 produits qui se vendent bien, avec de bonnes photos et des prix clairs. Vous ajouterez le reste après les premières ventes.","La boutique ne remplace pas WhatsApp, elle l’aide. Gardez WhatsApp pour discuter, et laissez la boutique montrer les produits et prendre les commandes."],"bullets":["Photos nettes, fond simple","Prix affiché clairement","Petite description qui donne envie","Bouton « Commander » bien visible sur le téléphone"]},{"title":"Le paiement et la livraison : là où on gagne ou on perd","paragraphs":["Au Cameroun, il FAUT le paiement Mobile Money. Les gens paient avec leur téléphone. Mettez MTN MoMo et Orange Money, avec une confirmation automatique — pas besoin d’envoyer une capture d’écran.","Pour la livraison, soyez clair : quelles zones, quel délai, quel prix. Un client rassuré va au bout de sa commande."],"quote":"Quand un client abandonne son panier, ce n’est presque jamais le produit. C’est un doute : sur le paiement, la livraison, ou le prix."},{"title":"Regardez ce qui se passe et améliorez","paragraphs":["Suivez 3 chiffres simples : combien de personnes visitent, combien mettent au panier, combien paient. L’endroit où ça bloque vous dit quoi corriger.","Changez une seule chose à la fois : une photo, un prix, un délai. C’est comme ça qu’une petite boutique devient une vraie machine à commandes."],"callout":"À retenir : Mobile Money bien visible + livraison claire + boutique rapide sur le téléphone. C’est la base pour vendre en ligne au Cameroun."}]'),
('Créer une boutique en ligne au Cameroun : le guide simple', 'Guide', '8 juillet 2026', '5 min', 'Créer une boutique en ligne au Cameroun, c’est ouvrir un magasin qui vend jour et nuit. Voici ce qu’il faut, combien ça coûte, et comment bien démarrer.', '/images/project-ecommerce.jpg', 0, 24, 1, 'Votre magasin ouvert 24h/24', 'Une boutique en ligne, c’est un magasin sur internet, ouvert jour et nuit. Au Cameroun, il vous faut un catalogue de produits, le paiement MTN MoMo et Orange Money, et une livraison organisée. À partir de 500 000 FCFA, tout compris la première année.', '/images/service-ecommerce.jpg', 'L’équipe IMPACT TECH', '[{"title":"Ce qu’il y a dans une boutique en ligne","paragraphs":["Une boutique, c’est vos produits rangés avec photos et prix, un panier, un paiement, et un espace pour vous où vous voyez les commandes qui arrivent. Le client choisit, paie, et vous êtes prévenu tout de suite.","Le plus important : que tout soit simple à utiliser sur le téléphone, parce que c’est là que vos clients achètent."],"bullets":["Vos produits avec photos et prix","Le panier et le paiement MoMo / Orange Money","Un espace pour gérer les commandes","La gestion des stocks (ce qui reste)"]},{"title":"Bien démarrer sans se compliquer","paragraphs":["Ne mettez pas 500 produits d’un coup. Commencez par ceux qui marchent le mieux. Une boutique claire avec 20 bons produits vend mieux qu’une boutique remplie mais confuse.","Prévoyez aussi comment vous allez livrer : vous-même, un livreur, un point de retrait ? Dites-le clairement sur la boutique."],"quote":"Une boutique en ligne qui marche, ce n’est pas la plus remplie. C’est la plus simple à utiliser et la plus rassurante pour payer."},{"title":"Combien ça coûte et ce que ça rapporte","paragraphs":["Comptez à partir de 500 000 FCFA pour une vraie boutique complète, domaine et hébergement de la première année inclus. Après, il reste juste le renouvellement chaque année.","Bien faite, une boutique se rembourse vite : elle vend même quand vous dormez, et centralise toutes vos commandes au même endroit."],"callout":"À retenir : commencez avec vos meilleurs produits, un paiement Mobile Money qui marche, et une livraison claire. On agrandit après."}]'),
('Comment être premier sur Google au Cameroun ?', 'Guide', '3 juillet 2026', '5 min', 'Comment être premier sur Google au Cameroun ? Il faut un site rapide, des pages qui répondent aux questions des gens, et une bonne fiche Google. Voici la méthode, en clair.', '/images/service-landing.jpg', 0, 25, 1, 'Être trouvé quand on vous cherche', 'Pour bien apparaître sur Google au Cameroun, il faut trois choses : un site rapide et propre, des pages qui répondent vraiment aux questions des gens (avec les mots qu’ils tapent), et une fiche Google bien remplie avec des avis. Les premiers résultats viennent en 2 à 4 mois.', '/images/blog-2.jpg', 'L’équipe IMPACT TECH', '[{"title":"Google montre des réponses, pas des entreprises","paragraphs":["Quand quelqu’un tape « créer boutique en ligne Douala », Google cherche la meilleure RÉPONSE à cette question. Si vous avez une page qui répond clairement, vous avez une chance d’être montré.","C’est pour ça qu’un blog aide : chaque article qui répond à une question devient une porte d’entrée sur votre site depuis Google."],"bullets":["Écrivez avec les mots simples que les gens tapent","Une page = une question précise","Répondez dès les premières lignes"]},{"title":"Votre fiche Google : le plus gros levier ici","paragraphs":["La fiche Google (celle qui apparaît sur la carte) est souvent plus efficace que le reste, surtout pour une entreprise locale. Remplissez-la bien : votre métier, votre ville, vos horaires, vos photos.","Et surtout, demandez des avis à vos clients contents. Les avis, c’est ce qui vous fait monter et ce qui rassure les nouveaux clients."],"quote":"Un client qui vous trouve sur la carte Google, avec de bonnes notes et des photos, vous choisit avant celui qu’on ne voit nulle part."},{"title":"Un peu de patience","paragraphs":["Google ne classe pas un site neuf du jour au lendemain. Il faut d’abord qu’il trouve votre site, qu’il le lise, puis qu’il vous fasse confiance. Ça prend des semaines, parfois des mois.","Le secret, c’est la régularité : un site propre + de nouveaux articles utiles de temps en temps + des avis. Petit à petit, vous montez."],"callout":"À retenir : site rapide + pages qui répondent aux vraies questions + fiche Google avec des avis. Et de la patience : le référencement, c’est un marathon."}]'),
('Pourquoi mon site n’apparaît pas sur Google ?', 'Conseils', '27 juin 2026', '4 min', 'Votre site existe mais on ne le trouve pas sur Google ? Voici les vraies raisons, expliquées simplement, et comment les régler.', '/images/blog-2.jpg', 0, 26, 1, 'Les raisons les plus fréquentes', 'Si votre site n’apparaît pas sur Google, c’est souvent l’une de ces raisons : le site est trop récent, il n’a pas été déclaré à Google, il est trop lent, il a peu de texte, ou vous cherchez avec le nom de votre entreprise au lieu des mots que tapent vos clients.', '/images/service-landing.jpg', 'L’équipe IMPACT TECH', '[{"title":"Le site est peut-être juste trop jeune","paragraphs":["Un site tout neuf n’est pas connu de Google tout de suite. Ça peut prendre quelques jours à quelques semaines avant qu’il commence à apparaître. C’est normal, ce n’est pas une panne.","Pour aller plus vite, il faut déclarer le site à Google avec un outil gratuit qui s’appelle Search Console. Beaucoup de sites « invisibles » n’ont simplement jamais été déclarés."],"bullets":["Site jamais déclaré à Google (Search Console)","Site trop récent (patience de quelques semaines)","Site trop lent sur le téléphone","Pages presque vides, sans texte utile"]},{"title":"Vous cherchez peut-être le mauvais mot","paragraphs":["Beaucoup de gens tapent le nom exact de leur entreprise et ne se voient pas. C’est normal : Google classe les pages sur les mots que cherchent les CLIENTS, pas le nom que vous connaissez déjà.","Testez avec les mots d’un client qui ne vous connaît pas : « couturier Douala », « site web pas cher », « boutique en ligne Cameroun ». C’est là que se joue la vraie visibilité."],"quote":"Google ne peut vous montrer que si vous lui donnez du texte à lire. Un site sans contenu, c’est une boutique sans enseigne."},{"title":"Le test simple à faire","paragraphs":["Tapez dans Google : site:votredomaine.com. Si vos pages s’affichent, votre site est bien connu de Google (le problème, c’est le classement, pas l’absence). Si rien ne s’affiche, il faut le déclarer."],"callout":"À retenir : la plupart du temps, « invisible sur Google » se règle en déclarant le site à Google + en ajoutant du vrai texte + un peu de patience."}]'),
('Comment mettre MTN MoMo et Orange Money sur son site ?', 'Guide', '22 juin 2026', '4 min', 'Vos clients paient avec leur téléphone. Voici comment ajouter le paiement MTN MoMo et Orange Money sur votre site, simplement et sans capture d’écran.', '/images/service-ecommerce.jpg', 0, 27, 1, 'Le paiement que vos clients utilisent déjà', 'Pour accepter MTN MoMo et Orange Money sur votre site, on relie votre boutique à un service de paiement qui gère les deux opérateurs. Le client paie avec son téléphone, et votre boutique est prévenue automatiquement que c’est payé. Fini les captures d’écran.', '/images/project-ecommerce.jpg', 'L’équipe IMPACT TECH', '[{"title":"Pourquoi c’est indispensable au Cameroun","paragraphs":["La plupart des gens ici n’ont pas de carte bancaire, mais tout le monde a MoMo ou Orange Money. Si votre site ne prend que la carte, vous perdez des ventes tous les jours.","Avec le Mobile Money, le client n’a besoin que de son numéro. C’est rapide, c’est ce qu’il connaît, et ça le rassure."],"bullets":["Un simple numéro de téléphone suffit","Paiement rapide, connu de tous","Confirmation automatique, sans attendre"]},{"title":"Comment ça marche techniquement (en simple)","paragraphs":["On branche votre boutique à un service de paiement fiable. Quand le client paie, ce service vérifie l’argent et prévient votre boutique : la commande passe toute seule de « en attente » à « payée ».","Évitez la méthode « envoyez-moi une capture d’écran du transfert » : c’est lent, ça fait des erreurs, et ça ouvre la porte aux fausses preuves de paiement."],"quote":"Le bon paiement, c’est celui que le client comprend sans poser de question, et qui se confirme sans que vous ayez à vérifier vous-même."},{"title":"Et les frais ?","paragraphs":["Chaque paiement en ligne prend une petite commission. Le mieux est de la prévoir dans vos prix, pour ne pas la subir. Demandez aussi en combien de temps l’argent arrive sur votre compte."],"callout":"À retenir : reliez votre site à un service qui gère MoMo et Orange Money, avec confirmation automatique. Jamais de paiement par capture d’écran."}]'),
('Site web ou page Facebook : qu’est-ce qui est mieux ?', 'Conseils', '18 juin 2026', '4 min', 'J’ai déjà une page Facebook, ai-je besoin d’un site ? Réponse simple : les deux servent à des choses différentes. Voici comment choisir.', '/images/blog-1.jpg', 0, 28, 1, 'La question que tout le monde se pose', 'La page Facebook attire l’attention aujourd’hui ; le site web, lui, vous appartient et reste trouvable pour toujours sur Google. Le mieux, c’est d’avoir les deux. Mais si vous devez choisir, le site est la base, parce qu’il est à vous.', '/images/service-blog.jpg', 'L’équipe IMPACT TECH', '[{"title":"Facebook, c’est bien… mais ce n’est pas à vous","paragraphs":["Facebook et Instagram sont super pour montrer votre quotidien et discuter avec les gens. Mais la page ne vous appartient pas : c’est Facebook qui décide qui voit vos publications, et un compte peut être bloqué du jour au lendemain.","Et surtout, votre page Facebook n’apparaît presque jamais dans Google quand quelqu’un cherche vos services."],"bullets":["C’est Facebook qui décide qui vous voit","Le compte peut être bloqué","Ça n’apparaît pas dans Google","Les publications disparaissent vite"]},{"title":"Le site web, lui, travaille pour vous","paragraphs":["Un site vous appartient à 100 %. Il travaille jour et nuit, apparaît sur Google, et rassure : beaucoup de clients regardent votre site avant de vous appeler.","C’est le seul endroit où vous contrôlez tout : le message, les prix, et la façon dont on vous contacte."],"quote":"Miser seulement sur Facebook, c’est construire sa maison sur le terrain d’un autre. Pratique, jusqu’au jour où le propriétaire change les règles."},{"title":"La bonne réponse : les deux ensemble","paragraphs":["Le mieux : Facebook pour attirer et discuter, le site pour rassurer et vendre. Vos publications ramènent les gens sur votre site, où ils passent à l’action.","Petit budget ? Commencez par le site, c’est la fondation. Vous ajouterez les réseaux dessus après."],"callout":"À retenir : Facebook = attention (loué). Site web = confiance et Google (à vous). Le premier amène les gens, le second les transforme en clients."}]'),
('C’est quoi un nom de domaine et un hébergement ? (mots simples)', 'Guide', '11 juin 2026', '4 min', 'Nom de domaine, hébergement, SSL : ces mots font peur mais les idées sont simples. On vous explique avec des images de tous les jours.', '/images/service-custom.jpg', 0, 29, 1, 'Les mots techniques, en clair', 'Le nom de domaine, c’est l’adresse de votre site (votreentreprise.com). L’hébergement, c’est le terrain où le site est construit et rangé. Le SSL (le cadenas), c’est la serrure qui sécurise. Les trois sont obligatoires pour un vrai site.', '/images/process-visual.jpg', 'L’équipe IMPACT TECH', '[{"title":"Le nom de domaine = votre adresse","paragraphs":["C’est comme l’adresse de votre boutique, mais sur internet : votreentreprise.com. On le paie une fois par an, et personne d’autre ne peut le prendre tant que vous le gardez.","Prenez-le court et facile à dire au téléphone. Le .com marche partout ; le .cm montre bien que vous êtes au Cameroun."]},{"title":"L’hébergement = le terrain où vit le site","paragraphs":["Si le nom est l’adresse, l’hébergement est le terrain et les fondations. C’est là que sont rangées vos pages et vos photos. Un bon hébergement garde le site en ligne tout le temps et le rend rapide, même en connexion faible.","Un hébergement pas cher mais lent vous fait perdre des clients sans que vous le voyiez. La vitesse, c’est un investissement."],"quote":"Nom de domaine (l’adresse) + hébergement (le terrain) + cadenas de sécurité : ce ne sont pas des options, ce sont les fondations."},{"title":"Le SSL = le cadenas qui rassure","paragraphs":["Le SSL, c’est le petit cadenas et le « https » devant l’adresse. Il protège les infos qui circulent (mot de passe, numéro de commande). Sans lui, le navigateur affiche « site non sécurisé » et Google vous pénalise.","Bonne nouvelle : chez un hébergeur sérieux, ce cadenas est aujourd’hui inclus et se met tout seul."],"callout":"À retenir : un vrai site a toujours ces trois choses. Chez nous, elles sont comprises dans le prix la première année."}]'),
('Comment créer une application mobile au Cameroun ?', 'Guide', '5 juin 2026', '5 min', 'Vous avez une idée d’application mobile au Cameroun ? Voici comment ça se passe, combien de temps ça prend, et comment éviter de dépenser pour rien.', '/images/service-app.jpg', 0, 30, 1, 'De l’idée à l’application', 'Pour créer une application mobile au Cameroun, on part de votre idée, on dessine les écrans, on développe une première version simple, on la teste avec de vrais utilisateurs, puis on l’améliore. Comptez environ 8 à 12 semaines pour une première version sérieuse.', '/images/project-delivery.jpg', 'L’équipe IMPACT TECH', '[{"title":"D’abord, avez-vous vraiment besoin d’une application ?","paragraphs":["Une application coûte plus cher qu’un site. Elle est utile quand les gens reviennent souvent, quand il faut des notifications, ou quand ça doit marcher même sans connexion. Sinon, un bon site sur téléphone suffit souvent.","Posez-vous la question honnêtement : est-ce qu’un site mobile bien fait ne réglerait pas déjà votre problème ? Ça évite de dépenser pour rien."],"bullets":["Les gens l’utilisent souvent → application","Besoin de notifications → application","Doit marcher hors connexion → application","Juste présenter/vendre → un site suffit"]},{"title":"Comment ça se passe, étape par étape","paragraphs":["On commence par comprendre le besoin réel, sur le terrain. Ensuite on dessine les écrans (des maquettes qu’on peut cliquer), puis on développe une première version qui fait l’essentiel.","On teste avec de vrais utilisateurs, on écoute leurs retours, et on améliore. C’est bien mieux que de tout construire d’un coup et découvrir les problèmes à la fin."],"quote":"Une bonne application locale commence par accepter la réalité du terrain : connexion faible, adresses compliquées, paiement mobile."},{"title":"Combien de temps et combien ça coûte","paragraphs":["Une première version sérieuse prend souvent 8 à 12 semaines. Le prix se fait sur devis, car il dépend beaucoup de ce que l’application doit faire.","Le bon conseil : commencez par la version la plus simple qui règle le vrai problème. On ajoute les fonctions une par une, une fois qu’on est sûr que ça marche."],"callout":"À retenir : ne construisez pas une application « au cas où ». Commencez petit, testez avec de vrais utilisateurs, puis grandissez."}]'),
('Faut-il refaire son vieux site web ? 7 signes qui disent oui', 'Conseils', '30 mai 2026', '4 min', 'Un vieux site peut faire fuir vos clients sans que vous le sachiez. Voici 7 signes simples qu’il est temps de le refaire.', '/images/service-custom.jpg', 0, 31, 1, 'Quand votre site vous fait perdre des clients', 'Il faut refaire votre site s’il est lent, s’il s’affiche mal sur le téléphone, si vous ne pouvez pas le modifier vous-même, s’il n’a pas le cadenas de sécurité, s’il n’apparaît pas sur Google, s’il fait « vieux », ou s’il ne parle plus de ce que vous faites aujourd’hui.', '/images/blog-2.jpg', 'L’équipe IMPACT TECH', '[{"title":"Les 7 signes à vérifier vous-même","paragraphs":["Prenez votre téléphone et regardez votre site comme un client. Certains problèmes se voient tout de suite, d’autres agissent en silence. Dans les deux cas, ils vous font perdre des clients."],"bullets":["Il met plus de 3 secondes à s’ouvrir","Il s’affiche mal sur le téléphone","Vous ne pouvez pas changer les textes vous-même","Il affiche « non sécurisé » (pas de cadenas)","On ne le trouve pas sur Google","Le design fait « vieux »","Il parle d’offres que vous ne faites plus"]},{"title":"Refaire ne veut pas dire tout jeter","paragraphs":["On garde ce qui marche : votre nom de domaine, vos textes utiles, vos pages déjà connues de Google. On répare juste ce qui bloque.","Le but n’est pas d’avoir « un nouveau site pour faire joli », mais un site qui ramène plus de clients : plus rapide, plus clair, plus rassurant."],"quote":"Un site vieux et lent envoie un message que vous ne diriez jamais à un client : « nous ne sommes plus vraiment à jour »."},{"title":"Attention à ne pas disparaître de Google","paragraphs":["Le piège quand on refait un site, c’est de tout perdre sur Google d’un coup. On l’évite en gardant les mêmes adresses de pages ou en mettant des redirections propres."],"callout":"À retenir : refaire un site, c’est réparer une machine à clients. On garde le nom de domaine et ce qui marche déjà, on corrige le reste."}]');
INSERT INTO faqs (question, answer, sort_order, active) VALUES
('Combien coûte un site web au Cameroun ?', 'Une page simple coûte environ 200 000 FCFA, un site vitrine environ 300 000 FCFA, et une boutique en ligne à partir de 500 000 FCFA. La première année, le nom de domaine et l’hébergement sont compris. Après, il reste juste un petit montant à renouveler chaque année.', 20, 1),
('J’ai déjà une page Facebook, ai-je vraiment besoin d’un site ?', 'Oui. Facebook attire l’attention mais ne vous appartient pas : le compte peut être bloqué et votre page n’apparaît presque jamais sur Google. Un site est à vous, il travaille jour et nuit et rassure les clients qui vérifient avant d’acheter. Le mieux, c’est d’avoir les deux.', 21, 1),
('Est-ce que mon site va bien marcher sur le téléphone ?', 'Oui, c’est notre priorité. On fait des sites qui s’affichent bien et rapidement sur le téléphone, même quand la connexion est faible. Comme presque tous vos clients sont sur mobile, c’est la première chose qu’on soigne.', 22, 1),
('Est-ce que je peux vendre en ligne sans boutique physique et sans gros stock ?', 'Oui, beaucoup de nos clients commencent comme ça : quelques produits, une boutique simple, le paiement MoMo et une livraison locale. On démarre petit, on regarde ce qui se vend, puis on agrandit selon la demande.', 23, 1),
('Vous mettez le paiement MTN MoMo et Orange Money ?', 'Oui, c’est indispensable au Cameroun. On intègre MTN Mobile Money et Orange Money (et les cartes bancaires si besoin), avec une confirmation automatique du paiement. Pas de capture d’écran à envoyer.', 24, 1),
('Comment mon site va apparaître sur Google ?', 'On déclare votre site à Google et on crée votre fiche Google (celle de la carte). On soigne aussi les textes avec les mots que vos clients tapent. Les premiers résultats arrivent en général en 2 à 4 mois, puis ça grossit, surtout si on publie des articles régulièrement.', 25, 1),
('Combien de temps pour avoir mon site en ligne ?', 'Environ 2 semaines pour une page simple, 3 semaines pour un site vitrine, 4 à 6 semaines pour une boutique en ligne. Le délai exact est écrit dans le devis. Ce qui accélère le plus, c’est d’avoir vos textes et vos photos prêts.', 26, 1),
('Le site m’appartient vraiment ? J’ai les accès ?', 'Oui, le site est à vous à 100 %. Le nom de domaine et les accès sont à votre nom : vous n’êtes jamais bloqué avec un prestataire. On vous forme pour être autonome, et on reste dispo si vous avez besoin d’aide.', 27, 1),
('Je peux payer en plusieurs fois ?', 'Oui. En général : un acompte au départ, un paiement à la validation du design, et le reste à la livraison. On s’adapte à votre trésorerie, il suffit d’en parler.', 28, 1),
('Vous faites des sites pas chers ?', 'On fait des sites au prix juste : tout est compris (design, domaine, hébergement 1 an, sécurité), et le prix est dit à l’avance, sans surprise. On trouve toujours une formule adaptée à votre budget, sans sacrifier la qualité.', 29, 1),
('Vous pouvez aussi faire le logo, les textes et retoucher les photos ?', 'Oui. Vous pouvez fournir vos éléments, ou nous confier les textes, le logo et la retouche de vos photos. On s’adapte à ce que vous avez déjà.', 30, 1),
('Vous travaillez avec des clients hors de Douala ?', 'Oui, partout au Cameroun et même à l’étranger, en visio. Les échanges, la formation et le support se font par WhatsApp et en ligne, aussi facilement qu’en présentiel.', 31, 1);
